class Solution:

    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()

        def check(m: int) -> bool:
            prev = start[0]
            for s in start[1:]:
                prev = max(s, prev + m)
                if prev > s + d:
                    return False
            return True
        low, high = (0, (start[-1] + d - start[0]) // (len(start) - 1))
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

