class Solution:

    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [0] * n
        for idx in targetIndices:
            is_target[idx] = 1
        dp = [-float('inf')] * (m + 1)
        dp[0] = 0
        for i, c in enumerate(source):
            cost = is_target[i]
            for j in range(m - 1, -1, -1):
                if c == pattern[j]:
                    if dp[j] > dp[j + 1] + cost:
                        dp[j + 1] = dp[j]
                    else:
                        dp[j + 1] += cost
                else:
                    dp[j + 1] += cost
            dp[0] += cost
        return dp[m]

