class Solution:

    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        max_heap = []
        results = []
        for x, y in queries:
            d = abs(x) + abs(y)
            if len(max_heap) < k:
                heapq.heappush(max_heap, -d)
            elif d < -max_heap[0]:
                heapq.heapreplace(max_heap, -d)
            if len(max_heap) < k:
                results.append(-1)
            else:
                results.append(-max_heap[0])
        return results

