    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        if k == 1:
            return nums
        results = []
        consec = 1
        for i in range(len(nums)):
            if i > 0 and nums[i] == nums[i - 1] + 1:
                consec += 1
            else:
                consec = 1
            if i >= k - 1:
                if consec >= k:
                    results.append(nums[i])
                else:
                    results.append(-1)
        return results

