class Solution:

    def countPairs(self, nums: List[int]) -> int:

        def check(x: int, y: int) -> bool:
            s1, s2 = (str(x), str(y))
            max_len = max(len(s1), len(s2))
            s1 = s1.zfill(max_len)
            s2 = s2.zfill(max_len)
            diff = [i for i in range(max_len) if s1[i] != s2[i]]
            if len(diff) == 0:
                return True
            if len(diff) == 2:
                i, j = diff
                return s1[i] == s2[j] and s1[j] == s2[i]
            return False
        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if check(nums[i], nums[j]):
                    ans += 1
        return ans

