class Solution:

    def maximumValueSum(self, board: List[List[int]]) -> int:
        """Calculates the maximum value sum of three cells chosen from three distinct rows, such that the cells in the first two rows share the same column index and the cell in the third row is in a different column, restricted to the top three cell values of each row.

Parameters:
    board (List[List[int]]): A 2D list of integers representing the grid of cell values.

Returns:
    int | float: The maximum sum of three cell values satisfying the row and column constraints among each row's three largest values, or -float('inf') if no valid configuration exists."""
        m, n = (len(board), len(board[0]))
        best = []
        for r in range(m):
            best.append(heapq.nlargest(3, ((board[r][c], c) for c in range(n))))
        ans = -float('inf')
        for r1, r2, r3 in itertools.combinations(range(m), 3):
            for v1, c1 in best[r1]:
                for v2, c2 in best[r2]:
                    if c1 != c2:
                        continue
                    for v3, c3 in best[r3]:
                        if c3 != c1 and c3 != c2:
                            val = v1 + v2 + v3
                            if val > ans:
                                ans = val
        return ans

