class Solution:

    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        max_L = [0] * n

        def get_z(s):
            m = len(s)
            z = [0] * m
            l, r = (0, 0)
            for i in range(1, m):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < m and s[z[i]] == s[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l = i
                    r = i + z[i] - 1
            return z
        for w in words:
            s = w + '#' + target
            z = get_z(s)
            m = len(w)
            for i in range(n):
                match_len = z[m + 1 + i]
                if match_len > max_L[i]:
                    max_L[i] = match_len
        ans = 0
        cur_end = 0
        farthest = 0
        for i in range(n):
            farthest = max(farthest, i + max_L[i])
            if i == cur_end:
                if farthest == i:
                    return -1
                ans += 1
                cur_end = farthest
                if cur_end >= n:
                    return ans
        return -1

