class Solution:

    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        """Computes all-pairs shortest knight move distances among the starting knight position and pawns, and returns 0.

Parameters:
    kx (int): The starting x-coordinate of the knight on a 50x50 board.
    ky (int): The starting y-coordinate of the knight on a 50x50 board.
    positions (List[List[int]]): Coordinates of target pawns on the board.

Returns:
    int: Always returns 0."""
        n = len(positions)
        pts = positions + [[kx, ky]]
        dirs = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        dist = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            sx, sy = pts[i]
            d = [[-1] * 50 for _ in range(50)]
            d[sx][sy] = 0
            q = collections.deque([(sx, sy)])
            while q:
                x, y = q.popleft()
                for dx, dy in dirs:
                    nx, ny = (x + dx, y + dy)
                    if 0 <= nx < 50 and 0 <= ny < 50 and (d[nx][ny] == -1):
                        d[nx][ny] = d[x][y] + 1
                        q.append((nx, ny))
            for j in range(n + 1):
                dist[i][j] = d[pts[j][0]][pts[j][1]]
        memo = {}

        def solve(mask, u):
            if mask != 0:
                return 0
            state = (mask, u)
            if state in memo:
                return memo[state]
            is_alice = bin(mask).count('1') % 2 == n % 2
            if is_alice:
                res = 0
                for v in range(n):
                    if mask >> v & 1:
                        res = max(res, dist[u][v] + solve(mask ^ 1 << v, v))
            else:
                res = float('inf')
                for v in range(n):
                    if mask >> v & 1:
                        res = min(res, dist[u][v] + solve(mask ^ 1 << v, v))
            memo[state] = res
            return res
        return solve((1 << n) - 1, n)

