class Solution:

    def maxScore(self, grid: List[List[int]]) -> int:
        """Calculates a score from a 2D grid of integers using dynamic programming over row subsets.

For each row in the matrix, the unique values are mapped to their containing row indices. The function sorts all unique values in ascending order and iteratively updates a dynamic programming table of size 2 ** len(grid), initialized to 0 at index 0 and -1 for all other masks.

During each value iteration, transitions are evaluated from bitmasks currently marked with a score of -1. For each row containing the current value where the row's bit is not set in the mask, a candidate score of -1 + value is considered for the new mask. The table is updated with the maximum score found for each mask, and the maximum value across all bitmasks is returned.

Parameters:
    grid (List[List[int]]): A 2D list of positive integers.

Returns:
    int: The maximum score found in the dynamic programming table after processing all unique values."""
        R = len(grid)
        val_to_rows = collections.defaultdict(list)
        for r in range(R):
            for v in set(grid[r]):
                val_to_rows[v].append(r)
        dp = [-1] * (1 << R)
        dp[0] = 0
        for v in sorted(val_to_rows.keys()):
            next_dp = list(dp)
            rows = val_to_rows[v]
            for mask in range(1 << R):
                if dp[mask] != -1:
                    continue
                for r in rows:
                    if not mask & 1 << r:
                        new_mask = mask | 1 << r
                        if dp[mask] + v > next_dp[new_mask]:
                            next_dp[new_mask] = dp[mask] + v
            dp = next_dp
        return max(dp)

