class Solution:

    def countWinningSequences(self, s: str) -> int:
        """Calculate the number of single-creature sequences that result in a strictly positive score against Alice's sequence.

Simulates the game under the condition that Bob selects one creature ('F', 'W', or 'E') and summons it in every round from round 0 to n - 1. A creature earns 1 point if it beats Alice's creature (Water beats Fire, Earth beats Water, Fire beats Earth), 0 points on a tie, and -1 point if it loses.

Parameters
----------
s : str
    A string of length `n` composed of characters 'F', 'W', and 'E', representing Alice's sequence of moves.

Returns
-------
int
    The number of unique constant sequences (from 0 to 3) where Bob's cumulative net score across all rounds is strictly greater than 0, modulo 10^9 + 7."""
        MOD = 10 ** 9 + 7
        n = len(s)
        mapping = {'F': 0, 'W': 1, 'E': 2}
        alice = [mapping[c] for c in s]
        score = [[0, -1, 1], [1, 0, -1], [-1, 1, 0]]
        OFFSET = n
        SIZE = 2 * n + 1
        dp = [[0] * SIZE for _ in range(3)]
        first_a = alice[0]
        for b in range(3):
            diff = score[b][first_a]
            dp[b][diff + OFFSET] = 1
        for i in range(1, n):
            a = alice[i]
            new_dp = [[0] * SIZE for _ in range(3)]
            for b in range(3):
                d = score[b][a]
                for prev_b in range(3):
                    if prev_b != b:
                        continue
                    prev_row = dp[prev_b]
                    if d == 1:
                        for diff_idx in range(SIZE - 1):
                            new_dp[b][diff_idx + 1] = (new_dp[b][diff_idx + 1] + prev_row[diff_idx]) % MOD
                    elif d == -1:
                        for diff_idx in range(1, SIZE):
                            new_dp[b][diff_idx - 1] = (new_dp[b][diff_idx - 1] + prev_row[diff_idx]) % MOD
                    else:
                        for diff_idx in range(SIZE):
                            new_dp[b][diff_idx] = (new_dp[b][diff_idx] + prev_row[diff_idx]) % MOD
            dp = new_dp
        ans = 0
        for b in range(3):
            for diff in range(OFFSET + 1, SIZE):
                ans = (ans + dp[b][diff]) % MOD
        return ans

