class Solution:

    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        """Calculates the maximum total fruits collected by three paths traversing an n x n grid.

The calculation combines:
1. The sum of all elements along the main diagonal from (0, 0) to (n - 1, n - 1).
2. The maximum fruit collection path starting from (0, n - 1) traversing row by row downwards to column n - 1 at row n - 2, constrained strictly above the diagonal (column index > row index).
3. The symmetric maximum fruit collection path starting from (n - 1, 0) traversing column by column rightwards, evaluated by running the same dynamic programming path search on the transposed grid.

Parameters:
    fruits (List[List[int]]): An n x n grid of non-negative integers representing the fruit counts in each room.

Returns:
    int: The sum of the main diagonal fruits and the maximum path sums obtained by the two non-diagonal paths."""
        n = len(fruits)
        diag_sum = sum((fruits[i][i] for i in range(n)))

        def solve(grid: List[List[int]]) -> int:
            dp = {n - 1: grid[0][n - 1]}
            for i in range(n - 2):
                next_dp = {}
                for j, val in dp.items():
                    for dj in (-1, 0, 1):
                        nj = j + dj
                        if nj > i + 1 and nj <= n:
                            next_dp[nj] = max(next_dp.get(nj, -1), val + grid[i + 1][nj])
                dp = next_dp
            return dp.get(n - 1, 0)
        transposed = [[fruits[j][i] for j in range(n)] for i in range(n)]
        return diag_sum + solve(fruits) + solve(transposed)

