class Solution:

    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        """Calculates the minimum possible sum of elements in nums after applying two types of operations up to their allowed limits.

For each element x in nums, the following operation choices are evaluated:
- No operations: contributes x.
- Operation 1 only (cost: 1 of op1): halves the value, contributing (x + 1) // 2.
- Operation 2 only (cost: 1 of op2): available if x > k, contributing x - k.
- Both operations (cost: 1 of op1, 1 of op2): available if (x + 1) // 2 >= k or x >= k. The resulting value is the minimum of (x + 1) // 2 - k (if (x + 1) // 2 >= k) and (x - k + 1) // 2 (if x >= k).

Dynamic programming is used across the elements to find the global minimum sum that requires at most op1 type 1 operations and at most op2 type 2 operations.

Parameters:
    nums (List[int]): The list of non-negative integers.
    k (int): The integer subtracted in Operation 2.
    op1 (int): The maximum number of Operation 1 applications allowed.
    op2 (int): The maximum number of Operation 2 applications allowed.

Returns:
    int: The minimum total sum achievable within the given operation constraints."""
        dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for x in nums:
            options = [(0, 0, x), (1, 0, (x + 1) // 2)]
            if x > k:
                options.append((0, 1, x - k))
            both_val = float('inf')
            if (x + 1) // 2 >= k:
                both_val = min(both_val, (x + 1) // 2 - k)
            if x >= k:
                both_val = min(both_val, (x - k + 1) // 2)
            if both_val != float('inf'):
                options.append((1, 1, both_val))
            new_dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
            for c1 in range(op1 + 1):
                for c2 in range(op2 + 1):
                    if dp[c1][c2] == float('inf'):
                        continue
                    for dc1, dc2, val in options:
                        nc1, nc2 = (c1 + dc1, c2 + dc2)
                        if nc1 <= op1 and nc2 <= op2:
                            if dp[c1][c2] + val < new_dp[nc1][nc2]:
                                new_dp[nc1][nc2] = dp[c1][c2] + val
            dp = new_dp
        return min((dp[c1][c2] for c1 in range(op1 + 1) for c2 in range(op2 + 1)))

