class Solution:

    def minDifference(self, nums: List[int]) -> int:
        """You are given an array of integers nums. Some values in nums are missing and are denoted by -1.
You can choose a pair of positive integers (x, y) exactly once and replace each missing element with either x or y.
You need to minimize the maximum absolute difference between adjacent elements of nums after replacements.
Return the minimum possible difference.

Example 1:

Input: nums = [1,2,-1,10,8]
Output: 4
Explanation:
By choosing the pair as (6, 7), nums can be changed to [1, 2, 6, 10, 8].
The absolute differences between adjacent elements are:

|1 - 2| == 1
|2 - 6| == 4
|6 - 10| == 4
|10 - 8| == 2


Example 2:

Input: nums = [-1,-1,-1]
Output: 0
Explanation:
By choosing the pair as (4, 4), nums can be changed to [4, 4, 4].

Example 3:

Input: nums = [-1,10,-1,8]
Output: 1
Explanation:
By choosing the pair as (11, 9), nums can be changed to [11, 10, 9, 8].


Constraints:

2 <= nums.length <= 10^5
nums[i] is either -1 or in the range [1, 10^9]."""
        n = len(nums)
        if all((x == -1 for x in nums)):
            return 0
        base_diff = 0
        for i in range(n - 1):
            if nums[i] != -1 and nums[i + 1] != -1:
                base_diff = max(base_diff, abs(nums[i] - nums[i + 1]))
        segments = []
        i = 0
        while i < n:
            if nums[i] == -1:
                j = i
                while j < n and nums[j] == -1:
                    j += 1
                left_neighbor = nums[i - 1] if i > 0 else None
                right_neighbor = nums[j] if j < n else None
                segments.append((j - i, left_neighbor, right_neighbor))
                i = j
            else:
                i += 1

        def can_cover(intervals, require_dist, d):
            if not intervals:
                return True
            for l, r in intervals:
                if l > r:
                    return False
            r_min = min((r for l, r in intervals))
            x = r_min
            uncovered = [iv for iv in intervals if not iv[0] <= x <= iv[1]]
            if not uncovered:
                return True
            l_prime_max = max((l for l, r in uncovered))
            r_prime_min = min((r for l, r in uncovered))
            if l_prime_max > r_prime_min:
                return False
            if require_dist:
                return l_prime_max - x <= d
            return True

        def check(d):
            if d < base_diff:
                return False
            intervals_a = []
            for length, left, right in segments:
                if length == 1:
                    if left is not None and right is not None:
                        intervals_a.append((max(left, right) - d, min(left, right) + d))
                    elif left is not None:
                        intervals_a.append((left - d, left + d))
                    elif right is not None:
                        intervals_a.append((right - d, right + d))
                else:
                    if left is not None:
                        intervals_a.append((left - d, left + d))
                    if right is not None:
                        intervals_a.append((right - d, right + d))
            if can_cover(intervals_a, True, d):
                return True
            intervals_b = []
            for length, left, right in segments:
                if left is not None and right is not None:
                    intervals_b.append((max(left, right) - d, min(left, right) + d))
                elif left is not None:
                    intervals_b.append((left - d, left + d))
                elif right is not None:
                    intervals_b.append((right - d, right + d))
            if can_cover(intervals_b, False, d):
                return True
            return False
        low, high = (base_diff, 10 ** 9)
        ans = high
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

