class Solution:

    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 1000000007
        m, n = (len(grid), len(grid[0]))
        dp = [[0] * 16 for _ in range(n)]
        dp[0][grid[0][0]] = 1
        for j in range(1, n):
            val = grid[0][j]
            for x in range(16):
                dp[j][x ^ val] = dp[j - 1][x]
        for i in range(1, m):
            new_dp = [[0] * 16 for _ in range(n)]
            val = grid[i][0]
            for x in range(16):
                new_dp[0][x ^ val] = dp[0][x]
            for j in range(1, n):
                val = grid[i][j]
                for x in range(16):
                    new_dp[j][x ^ val] = (dp[j][x] + new_dp[j - 1][x]) % MOD
            dp = new_dp
        return dp[n - 1][k]

