class Solution:

    def countComponents(self, nums: List[int], threshold: int) -> int:
        """Calculate the number of connected components in an undirected graph formed by elements of `nums` where an edge connects two nodes if their least common multiple (LCM) is at most `threshold`.

Elements in `nums` strictly greater than `threshold` cannot share an edge with any other element and each form their own isolated component. For elements less than or equal to `threshold`, the function uses a Disjoint Set Union (DSU) structure to group elements that share common multiples up to `threshold`.

Parameters:
    nums (List[int]): A list of unique positive integers representing the nodes in the graph.
    threshold (int): The maximum allowed LCM for an edge to exist between two nodes.

Returns:
    int: The total number of connected components in the graph."""
        small_nums = [x for x in nums if x <= threshold]
        ans = len(nums) - len(small_nums)
        if not small_nums:
            return ans
        parent = {x: x for x in small_nums}

        def find(i: int) -> int:
            path = []
            while parent[i] == i:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i: int, j: int) -> bool:
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False
        comp_count = len(small_nums)
        first_div = [0] * (threshold + 1)
        for x in small_nums:
            for m in range(x, threshold + 1, x):
                if first_div[m] == 0:
                    first_div[m] = x
                elif union(x, first_div[m]):
                    comp_count -= 1
        return ans + comp_count

