class Solution:

    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        groups = []
        count = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                count += 1
            else:
                groups.append(count)
                count = 1
        groups.append(count)

        def check(k: int) -> bool:
            if k == 1:
                cost1 = sum((1 for i, c in enumerate(s) if c != ('0' if i % 2 == 0 else '1')))
                cost2 = sum((1 for i, c in enumerate(s) if c != ('1' if i % 2 == 0 else '0')))
                return min(cost1, cost2) <= numOps
            else:
                cost = sum((L // (k + 1) for L in groups))
                return cost <= numOps
        low, high = (1, n)
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

