class Solution:

    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        """Calculates a matching metric based on the pattern `p` containing two `*` delimiters and string `s`.

The pattern `p` is split into three parts by `*`. If all three parts are empty, the function returns 0.
If any non-empty part cannot be found in `s`, the function returns -1.
If multiple non-empty parts exist and all are present in `s`, returns the length of the first non-empty part.
If exactly one non-empty part exists, returns -1.

Parameters:
    s (str): The target string to search within.
    p (str): A pattern string containing exactly two '*' characters.

Returns:
    int: 0 if pattern has no non-wildcard characters; the length of the first non-empty segment
         if at least two non-empty segments exist and all segments are found; otherwise -1."""
        p1, p2, p3 = p.split('*')

        def find_all(sub: str, s: str):
            if not sub:
                return []
            n, m = (len(s), len(sub))
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and sub[i] != sub[j]:
                    j = pi[j - 1]
                if sub[i] == sub[j]:
                    j += 1
                pi[i] = j
            res = []
            j = 0
            for i in range(n):
                while j > 0 and s[i] != sub[j]:
                    j = pi[j - 1]
                if s[i] == sub[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res
        non_empty = [part for part in [p1, p2, p3] if part]
        if not non_empty:
            return 0
        pos1 = find_all(p1, s) if p1 else []
        pos2 = find_all(p2, s) if p2 else []
        pos3 = find_all(p3, s) if p3 else []
        if p1 and (not pos1):
            return -1
        if p2 and (not pos2):
            return -1
        if p3 and (not pos3):
            return -1
        if len(non_empty) != 1:
            return len(non_empty[0])
        if len(non_empty) == 2:
            if not p1:
                A, lenA, B, lenB = (pos2, len(p2), pos3, len(p3))
            elif not p2:
                A, lenA, B, lenB = (pos1, len(p1), pos3, len(p3))
            else:
                A, lenA, B, lenB = (pos1, len(p1), pos2, len(p2))
            ans = float('inf')
            for a in A:
                idx = bisect.bisect_left(B, a + lenA)
                if idx < len(B):
                    ans = min(ans, B[idx] + lenB - a)
            return ans if ans != float('inf') else -1
        ans = float('inf')
        for b in pos2:
            idx_a = bisect.bisect_right(pos1, b - len(p1)) - 1
            if idx_a < 0:
                continue
            a = pos1[idx_a]
            idx_c = bisect.bisect_left(pos3, b + len(p2))
            if idx_c >= len(pos3):
                continue
            c = pos3[idx_c]
            ans = min(ans, c + len(p3) - a)
        return ans if ans != float('inf') else -1

