class Solution:

    def countSubstrings(self, s: str) -> int:
        dp = [[0] * d for d in range(1, 10)]
        ans = 0
        for ch in s:
            x = ord(ch) - 48
            new_dp = [[0] * d for d in range(1, 10)]
            for d in range(1, 10):
                d_idx = d - 1
                curr = dp[d_idx]
                nxt = new_dp[d_idx]
                for r in range(d):
                    val = curr[r]
                    if val:
                        nxt[(r * 10 + x) % d] += val
                nxt[x % d] += 1
            if x != 0:
                ans += new_dp[x - 1][0]
            dp = new_dp
        return ans

