class Solution:

    def minCostGoodCaption(self, caption: str) -> str:
        """Transforms a string into a sequence of uniform character blocks of lengths 3, 4, or 5 with minimum total character modification cost, breaking ties to produce the lexicographically smallest result.

For strings of length 3 or shorter, or if no valid partitioning can be constructed, an empty string is returned.

Parameters:
    caption (str): The input string consisting of lowercase English letters.

Returns:
    str: The resulting modified string partitioned into uniform blocks of length 3 to 5, or an empty string if length is at most 3 or unreachable."""
        n = len(caption)
        if n <= 3:
            return ''
        ord_a = ord('a')
        arr = [ord(ch) - ord_a for ch in caption]
        INF = float('inf')
        dp_cost = [INF] * (n + 1)
        dp_cost[n] = 0
        dp_next = [(0, 0)] * (n + 1)

        def get_char(k, offset):
            curr = k
            while curr < n:
                L, c = dp_next[curr]
                if offset < L:
                    return c
                offset -= L
                curr += L
            return -1

        def is_better(L1, c1, L2, c2, i):
            if c1 != c2:
                return c1 < c2
            if L1 == L2:
                return False
            min_L = min(L1, L2)
            for offset in range(min_L, min_L + 15):
                char1 = c1 if offset < L1 else get_char(i + L1, offset - L1)
                char2 = c2 if offset < L2 else get_char(i + L2, offset - L2)
                if char1 != char2:
                    return char1 < char2
            return False
        for i in range(n - 3, -1, -1):
            best_c_total = INF
            best_choice = None
            for L in (3, 4, 5):
                if i + L > n:
                    continue
                if dp_cost[i + L] == INF:
                    continue
                sub = arr[i:i + L]
                for c in range(26):
                    cost = sum((abs(x - c) for x in sub)) + dp_cost[i + L]
                    if cost < best_c_total:
                        best_c_total = cost
                        best_choice = (L, c)
                    elif cost == best_c_total:
                        if best_choice is None or is_better(L, c, best_choice[0], best_choice[1], i):
                            best_choice = (L, c)
            if best_choice is not None:
                dp_cost[i] = best_c_total
                dp_next[i] = best_choice
        if dp_cost[0] == INF:
            return ''
        res = []
        curr = 0
        while curr < n:
            L, c = dp_next[curr]
            res.append(chr(ord_a + c) * L)
            curr += L
        return ''.join(res)

