class Solution:

    def minCost(self, n: int, cost: List[List[int]]) -> int:
        """Calculates the minimum cost to paint n houses arranged symmetrically from both ends.

For the outermost pair of houses (indices 0 and n - 1), both houses are assigned the same color. For every subsequent equidistant pair (indices i and n - 1 - i for 1 <= i < n // 2), the two houses must have distinct colors, and neither house may share a color with its adjacent predecessor from the previous pair.

Parameters:
    n (int): The number of houses, guaranteed to be even.
    cost (List[List[int]]): An n x 3 list where cost[i][j] is the cost to paint house i with color j (0, 1, or 2).

Returns:
    int: The minimum total cost to paint all houses satisfying the constraints, or infinity if n is invalid or no valid color configuration exists."""
        dp = [[float('inf')] * 3 for _ in range(3)]
        for c1 in range(3):
            for c2 in range(3):
                if c1 == c2:
                    dp[c1][c2] = cost[0][c1] + cost[n - 1][c2]
        for i in range(1, n // 2):
            new_dp = [[float('inf')] * 3 for _ in range(3)]
            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue
                    best = float('inf')
                    for pc1 in range(3):
                        if pc1 == c1:
                            continue
                        for pc2 in range(3):
                            if pc2 == c2:
                                continue
                            if dp[pc1][pc2] < best:
                                best = dp[pc1][pc2]
                    new_dp[c1][c2] = best + cost[i][c1] + cost[n - 1 - i][c2]
            dp = new_dp
        return min((dp[c1][c2] for c1 in range(3) for c2 in range(3)))

