class Solution:

    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        """Assigns each group the smallest index of an element that divides the group's value, provided the element's value is strictly less than the maximum value in `groups`.

For each group size in `groups`, finds the first-occurring index `j` in `elements` such that `elements[j] < max(groups)` and `groups[i] % elements[j] == 0`. If multiple candidate elements divide a group's value, the one with the smallest index `j` is chosen. If no element strictly less than `max(groups)` divides the group's value, `-1` is assigned.

Parameters:
    groups (List[int]): A list of positive integers representing group sizes.
    elements (List[int]): A list of positive integers representing available elements.

Returns:
    List[int]: A list where each entry corresponds to the smallest index in `elements` dividing the group value (subject to `elements[j] < max(groups)`), or `-1` if no such element exists."""
        max_val = max(groups)
        min_idx = [-1] * (max_val + 1)
        seen = {}
        for j, e in enumerate(elements):
            if e < max_val and e not in seen:
                seen[e] = j
        for e, j in seen.items():
            for multiple in range(e, max_val + 1, e):
                if min_idx[multiple] == -1 or j < min_idx[multiple]:
                    min_idx[multiple] = j
        return [min_idx[g] for g in groups]

