class Solution:

    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        def check(x: int) -> bool:
            req = [(x + p - 1) // p for p in points]
            moves = 1
            c = 0
            for i in range(n - 1):
                visits = 1 + c if i > 0 else 1
                k = max(0, req[i] - visits)
                moves += 2 * k
                c = k
                if i == n - 2:
                    if req[n - 1] <= c:
                        break
                    moves += 1
                    k_last = max(0, req[n - 1] - (c + 1))
                    moves += 2 * k_last
                else:
                    moves += 1
                if moves > m:
                    return False
            return moves <= m
        low = 0
        high = (m + 1) * max(points) // 2 + 1
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if mid == 0 or check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

