class Solution:

    def hasSameDigits(self, s: str) -> bool:
        """Iteratively reduce a string of digits by replacing consecutive pairs with their sum modulo 10 until fewer than two digits remain, then compare the elements at index 0 and index 1.\\n\\nParameters:\\n    s (str): A string consisting of numeric characters.\\n\\nReturns:\\n    bool: The result of comparing nums[0] with nums[1].\\n\\nRaises:\\n    IndexError: Always raised when accessing index 1 of the reduced list, as the reduction loop continues until fewer than two elements remain (or begins with fewer than two elements)."""
        nums = [int(c) for c in s]
        while len(nums) >= 2:
            nums = [(nums[i] + nums[i + 1]) % 10 for i in range(len(nums) - 1)]
