class Solution:

    def generateString(self, str1: str, str2: str) -> str:
        """Construct and return a string of length len(str1) + len(str2) - 1 based on constraint matching against str2.

The algorithm performs the following steps:
1. Initializes a list of characters of length n + m - 1 with None.
2. Iterates over each index i where str1[i] != 'T', placing str2 at indices [i, i + m - 1]. If an overlapping character already exists and does not match str2, returns an empty string "".
3. For each index i where str1[i] == 'F', counts unset positions and mismatches against str2. If any such interval has zero unset positions and zero mismatches, returns "".
4. Fills any remaining unset positions in the template with the lexicographically smallest lowercase character ('a' through 'z') that avoids forbidden mismatches ending at that index.
5. Returns the joined string.

Parameters:
    str1 (str): A string consisting of 'T' and/or 'F' characters of length n.
    str2 (str): A pattern string of lowercase English letters of length m.

Returns:
    str: The constructed string of length n + m - 1, or "" if validation fails.

Examples:
    >>> s = Solution()
    >>> s.generateString("TT", "ab")
    'aaa'
    >>> s.generateString("TFTF", "ab")
    ''"""
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1
        word = [None] * total_len
        for i in range(n):
            if str1[i] != 'T':
                for j in range(m):
                    if word[i + j] is not None and word[i + j] != str2[j]:
                        return ''
                    word[i + j] = str2[j]
        mismatches = [0] * n
        free_count = [0] * n
        last_free = [-1] * n
        intervals_ending_at = [[] for _ in range(total_len)]
        for i in range(n):
            if str1[i] == 'F':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        free_count[i] += 1
                        last_free[i] = pos
                    elif word[pos] != str2[j]:
                        mismatches[i] += 1
                if free_count[i] == 0 and mismatches[i] == 0:
                    return ''
                if free_count[i] > 0:
                    intervals_ending_at[last_free[i]].append(i)
        for k in range(total_len):
            if word[k] is None:
                forbidden = set()
                for i in intervals_ending_at[k]:
                    if mismatches[i] == 0:
                        forbidden.add(str2[k - i])
                for code in range(ord('a'), ord('z') + 1):
                    c = chr(code)
                    if c not in forbidden:
                        word[k] = c
                        break
                for i in range(max(0, k - m + 1), min(n, k + 1)):
                    if str1[i] == 'F':
                        if word[k] != str2[k - i]:
                            mismatches[i] += 1
        return ''.join(word)

