class Solution:

    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first = {}
        last = {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i
        intervals = []
        for ch in first:
            l = first[ch]
            r = last[ch]
            valid = True
            i = l
            while i <= r:
                curr_ch = s[i]
                if first[curr_ch] < l:
                    valid = False
                    break
                r = max(r, last[curr_ch])
                i += 1
            if valid and (not (l == 0 and r == n - 1)):
                intervals.append((l, r))
        intervals.sort(key=lambda x: x[1])
        count = 0
        prev_end = -1
        for l, r in intervals:
            if l > prev_end:
                count += 1
                prev_end = r
        return count >= k

