class Solution:

    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        """Calculates the maximum product among non-empty subsequences of nums whose alternating sum equals k, subject to upper bound limits.

The alternating sum is formed by adding elements at even indices (0-indexed within the subsequence) and subtracting elements at odd indices. During accumulation, single-element subsequences must satisfy element <= limit, transitions extending an odd-length subsequence must satisfy product <= limit, and transitions extending an even-length subsequence must satisfy product < limit.

Parameters:
    nums (List[int]): The list of non-negative integers.
    k (int): The target alternating sum.
    limit (int): The upper limit threshold for intermediate and final subsequence products.

Returns:
    int: The maximum product among all valid subsequences matching alternating sum k, or -1 if abs(k) > 1800 or if no valid subsequence exists."""
        if abs(k) > 150 * 12:
            return -1
        dp0 = collections.defaultdict(set)
        dp1 = collections.defaultdict(set)
        for x in nums:
            add0 = collections.defaultdict(set)
            add1 = collections.defaultdict(set)
            if x <= limit:
                add1[x].add(x)
            for s, prods in dp0.items():
                ns = s + x
                for p in prods:
                    np = p * x
                    if np < limit:
                        add1[ns].add(np)
            for s, prods in dp1.items():
                ns = s - x
                for p in prods:
                    np = p * x
                    if np <= limit:
                        add0[ns].add(np)
            for s, prods in add0.items():
                dp0[s].update(prods)
            for s, prods in add1.items():
                dp1[s].update(prods)
        res_prods = dp0[k] | dp1[k]
        return max(res_prods) if res_prods else -1

