class Solution:

    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        """Calculates the maximum possible minimum Manhattan distance between k points selected from the boundary of a square of a given side length.

The algorithm sorts the points in counter-clockwise order along the boundary of the square and uses binary search over possible distance values in the range [1, side]. For each candidate distance, a greedy selection check with circular traversal determines if k points can be chosen such that the Manhattan distance between every adjacent pair in the selection (including the last and first) is at least the target distance.

Parameters:
    side (int): The side length of the square spanning from (0, 0) to (side, side).
    points (List[List[int]]): A list of 2D coordinates representing points on the boundary of the square.
    k (int): The number of points to select.

Returns:
    int: The maximum minimum Manhattan distance found among valid selections of k points."""

        def get_pos(p: List[int]) -> int:
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 3 * side - x
            else:
                return 4 * side - y
        points.sort(key=get_pos)
        n = len(points)

        def dist(p1: List[int], p2: List[int]) -> int:
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def check(d: int) -> bool:
            next_hop = [-1] * n
            j = 0
            for i in range(n):
                j = max(j, i + 1)
                while j < i + n and dist(points[i], points[j % n]) < d:
                    j += 1
                if j < i + n:
                    next_hop[i] = j
                else:
                    next_hop[i] = -1
            if next_hop[0] == -1:
                return False
            limit = min(next_hop[0], n - 1)
            for start in range(limit + 1):
                curr = start
                possible = True
                for _ in range(k - 1):
                    nxt = next_hop[curr % n]
                    if nxt == -1:
                        possible = False
                        break
                    curr = curr + (nxt - curr % n)
                    if curr >= start + n:
                        possible = False
                        break
                if possible and dist(points[curr % n], points[start]) >= d:
                    return True
            return False
        low, high = (1, side)
        ans = 1
        while low < high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

