class Solution:

    def permute(self, n: int, k: int) -> List[int]:
        """Construct the k-th lexicographically ordered alternating permutation of integers from 1 to n.

An alternating permutation is a permutation of integers {1, 2, ..., n} where adjacent elements alternate between odd and even parity. For an odd value of n, permutations must start with an odd integer.

Parameters:
    n (int): The maximum integer in the permutation.
    k (int): The 1-based index of the alternating permutation in lexicographical order.

Returns:
    List[int]: The k-th alternating permutation, or an empty list if k exceeds the total count of permutations allowed by the initial capacity check.

Examples:
    >>> s = Solution()
    >>> s.permute(4, 6)
    [3, 4, 1, 2]
    >>> s.permute(3, 2)
    [3, 2, 1]
    >>> s.permute(2, 3)
    []"""
        odds = [x for x in range(1, n + 1) if x % 2 == 1]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]
        if n % 2 != 1:
            total = math.factorial(len(odds)) * math.factorial(len(evens))
        else:
            total = 2 * math.factorial(len(odds)) * math.factorial(len(evens))
        if k > total:
            return []
        res = []
        for p in range(n):
            if p == 0:
                if n % 2 == 1:
                    candidates = [(x, 1) for x in odds]
                else:
                    candidates = sorted([(x, 1) for x in odds] + [(x, 0) for x in evens])
            else:
                req_parity = 1 - res[-1] % 2
                if req_parity == 1:
                    candidates = [(x, 1) for x in odds]
                else:
                    candidates = [(x, 0) for x in evens]
            for x, par in candidates:
                if par == 1:
                    ways = math.factorial(len(odds) - 1) * math.factorial(len(evens))
                else:
                    ways = math.factorial(len(odds)) * math.factorial(len(evens) - 1)
                if k <= ways:
                    res.append(x)
                    if par == 1:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    break
                else:
                    k -= ways
        return res

