class Solution:

    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        """Computes the maximum common prefix length among any k strings remaining after removing each word.

For each word at index i, evaluates the array of words with words[i] excluded. If the remaining number of words (len(words) - 1) is less than or equal to k, the result for all indices is 0. Otherwise, builds a prefix trie of all words, establishes DFS entry and exit timestamps for trie nodes, and calculates prefix/suffix maximum depths for nodes with frequency at least k. For each string, determines the deepest prefix with frequency at least k + 1 along its trie path, combines it with the maximum valid depth outside its terminal node's subtree, and stores the maximum.

Parameters:
    words (List[str]): A list of lowercase English strings.
    k (int): The target number of strings to find a common prefix among.

Returns:
    List[int]: A list of integers where the i-th element represents the maximum length of a common prefix among k strings when words[i] is removed."""
        n = len(words)
        if n - 1 <= k:
            return [0] * n
        trie = [{'children': {}, 'count': 0, 'depth': 0}]
        for word in words:
            curr = 0
            trie[curr]['count'] += 1
            for ch in word:
                if ch not in trie[curr]['children']:
                    trie.append({'children': {}, 'count': 0, 'depth': trie[curr]['depth'] + 1})
                    trie[curr]['children'][ch] = len(trie) - 1
                curr = trie[curr]['children'][ch]
                trie[curr]['count'] += 1
        num_nodes = len(trie)
        tin = [0] * num_nodes
        tout = [0] * num_nodes
        timer = 0
        stack = [(0, False)]
        while stack:
            u, visited = stack.pop()
            if visited:
                tout[u] = timer - 1
            else:
                tin[u] = timer
                timer += 1
                stack.append((u, True))
                for ch, v in trie[u]['children'].items():
                    stack.append((v, False))
        pref_max = [0] * (timer + 1)
        suff_max = [0] * (timer + 1)
        for u in range(num_nodes):
            if trie[u]['count'] >= k:
                d = trie[u]['depth']
                L = tin[u] - 1
                R = tout[u] + 1
                if L >= 0:
                    if d > pref_max[L]:
                        pref_max[L] = d
                if R < timer:
                    if d > suff_max[R]:
                        suff_max[R] = d
        for i in range(timer - 2, -1, -1):
            if pref_max[i + 1] > pref_max[i]:
                pref_max[i] = pref_max[i + 1]
        for i in range(1, timer):
            if suff_max[i - 1] > suff_max[i]:
                suff_max[i] = suff_max[i - 1]
        ans = [0] * n
        for i, word in enumerate(words):
            curr = 0
            path_max = 0
            for ch in word:
                curr = trie[curr]['children'][ch]
                if trie[curr]['count'] >= k + 1:
                    path_max = max(path_max, trie[curr]['depth'])
            leaf_t = tin[curr]
            outside_max = max(pref_max[leaf_t], suff_max[leaf_t])
            ans[i] = max(path_max, outside_max)
        return ans

