class Solution:

    def beautifulNumbers(self, l: int, r: int) -> int:
        """You are given two positive integers, l and r. A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.
Return the count of beautiful numbers between l and r, inclusive.

Example 1:

Input: l = 10, r = 20
Output: 2
Explanation:
The beautiful numbers in the range are 10 and 20.

Example 2:

Input: l = 1, r = 15
Output: 10
Explanation:
The beautiful numbers in the range are 1, 2, 3, 4, 5, 6, 7, 8, 9, and 10.


Constraints:

1 <= l <= r < 10^9"""

        def count(n: int) -> int:
            if n <= 0:
                return 0
            s_n = str(n)
            digits = [int(c) for c in s_n]
            n_digits = len(digits)
            max_sum = 9 * n_digits
            total = 0
            for S in range(1, max_sum + 1):

                @lru_cache(None)
                def dp(idx: int, is_less: bool, is_started: bool, cur_sum: int, cur_prod: int) -> int:
                    if cur_sum > S:
                        return 0
                    if idx == n_digits:
                        return 1 if is_started and cur_sum == S and (cur_prod == 0) else 0
                    limit = 9 if is_less else digits[idx]
                    ans = 0
                    for d in range(limit + 1):
                        nxt_less = is_less or d < limit
                        if not is_started:
                            if d == 0:
                                ans += dp(idx + 1, True, False, 0, 1 % S)
                            else:
                                ans += dp(idx + 1, nxt_less, True, d, d % S)
                        else:
                            ans += dp(idx + 1, nxt_less, True, cur_sum + d, cur_prod * d % S)
                    return ans
                total += dp(0, False, False, 0, 1 % S)
            return total
        return count(r) - count(l - 1)

